/* rho -> table-index scale, precomputed once (compile-time constants only)
 * instead of dividing by TYRE_LUT_RHO_MAX/(TYRE_LUT_SIZE-1) on every call --
 * this function runs on a hot path (see vehicle/tyre.c) on hardware with no
 * fast float divide. Mathematically identical to the generator's original
 * "step = RHO_MAX/(SIZE-1); pos = rho/step", just reassociated into one
 * multiply. */
static const float kInvRhoStep = (float)(TYRE_LUT_SIZE - 1) / TYRE_LUT_RHO_MAX;

float tyre_lut_lookup(TyreTuning tuning, TyreSurface surface, float rho)
{
    const float *table = g_tyre_lut[tuning][surface];
    float pos, frac;
    int i0;

    /* Note the negated form: `!(rho > 0.0f)`, not `rho <= 0.0f`. Every
     * comparison against a NaN is false, so a NaN rho fails this guard AND
     * fails the `pos >= TYRE_LUT_SIZE - 1` clamp below, falls through both,
     * and reaches `(int)pos` -- which for a NaN is undefined and in practice
     * gives INT_MIN, indexing the table catastrophically out of bounds.
     *
     * Measured, not theorised: an uninitialised slip_speed_floor produced
     * exactly this, and AddressSanitizer caught it right here as "SEGV on
     * unknown address ... READ memory access". On the 3DS there is no
     * sanitizer and no MMU trap -- it reads whatever happens to be at that
     * address and drives on with a garbage grip value, or hangs the console.
     *
     * This is a backstop, not a licence: a NaN arriving here still means a
     * caller computed a bad slip, and that caller is the real bug. */
    if (!(rho > 0.0f)) {
        return table[0];
    }

    pos = rho * kInvRhoStep;
    if (pos >= (float)(TYRE_LUT_SIZE - 1)) {
        return table[TYRE_LUT_SIZE - 1];
    }

    i0 = (int)pos;
    frac = pos - (float)i0;
    return table[i0] * (1.0f - frac) + table[i0 + 1] * frac;
}

float tyre_lut_rho(TyreSurface surface, float sr, float alpha_deg)
{
    const TyreLutSurfaceParams *p = &g_tyre_surface_params[surface];
    float a = sr / p->sr_peak;
    float b = alpha_deg / p->alpha_peak_deg;
    return sqrtf(a * a + b * b);
}

void tyre_lut_split(TyreSurface surface, float sr, float alpha_deg,
                     float f_mag, float *fx, float *fy)
{
    const TyreLutSurfaceParams *p = &g_tyre_surface_params[surface];
    float rho = tyre_lut_rho(surface, sr, alpha_deg);
    if (rho < 1e-6f) {
        *fx = 0.0f;
        *fy = 0.0f;
        return;
    }
    {
        float ux = (sr / p->sr_peak) / rho;
        float uy = (alpha_deg / p->alpha_peak_deg) / rho;
        *fx = f_mag * ux;
        *fy = f_mag * uy;
    }
}
